def max_index(nums: list) -> int:
    if not nums:
        return -1
    max_val = nums[0]
    max_idx = 0
    for i in range(1, len(nums)):
        if nums[i] > max_val:
            max_val = nums[i]
            max_idx = i
    return max_idx
